'use client';

import { useEffect, useState } from 'react';
import { supabase, Product } from '@/lib/supabase';
import { ProductCard } from '@/components/ProductCard';
import { CartDrawer } from '@/components/CartDrawer';
import { ProductDetailModal } from '@/components/ProductDetailModal';
import { useCart } from '@/store/useCart';
import { ShoppingBag, Search, Flower2 } from 'lucide-react';

interface Category {
  id: string;
  name: string;
  slug: string;
}

export default function Home() {
  const [products, setProducts] = useState<Product[]>([]);
  const [categoriesList, setCategoriesList] = useState<Category[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('ALL');
  const [loading, setLoading] = useState(true);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  const cartItems = useCart((state) => state.items);
  const totalItemsCount = cartItems.reduce((acc, item) => acc + item.quantity, 0);

  // Número de WhatsApp de la Florería
  const WHATSAPP_NUMBER = '529931234567';

  useEffect(() => {
    async function fetchData() {
      const [prodRes, catRes] = await Promise.all([
        supabase.from('products').select('*'),
        supabase.from('categories').select('*').order('name')
      ]);

      if (prodRes.data) setProducts(prodRes.data);
      if (catRes.data) setCategoriesList(catRes.data);
      setLoading(false);
    }
    fetchData();
  }, []);

  const filteredProducts = products.filter((p) => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory =
      selectedCategory === 'ALL' ||
      p.category?.toLowerCase() === selectedCategory.toLowerCase() ||
      selectedCategory.toLowerCase() === 'todos';
    return matchesSearch && matchesCategory;
  });

  const dynamicCategories = categoriesList.filter(
    (cat) => cat.slug.toLowerCase() !== 'todos' && cat.name.toLowerCase() !== 'todos'
  );

  return (
    <div className="min-h-screen bg-gradient-to-b from-pink-50/50 to-white text-gray-800">
      {/* Header Navbar */}
      <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-pink-100 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-pink-600 text-white rounded-xl">
              <Flower2 className="w-6 h-6" />
            </div>
            <div>
              <h1 className="font-black text-xl text-gray-900 leading-tight">
                Florería VJM
              </h1>
              <p className="text-xs text-pink-600 font-medium">Catálogo Digital</p>
            </div>
          </div>

          <button
            onClick={() => setIsCartOpen(true)}
            className="relative p-2.5 bg-pink-100 text-pink-700 rounded-xl hover:bg-pink-200 transition"
          >
            <ShoppingBag className="w-5 h-5" />
            {totalItemsCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-pink-600 text-white text-xs font-bold rounded-full h-5 w-5 flex items-center justify-center animate-bounce">
                {totalItemsCount}
              </span>
            )}
          </button>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-6xl mx-auto px-4 py-8">
        {/* Banner Hero */}
        <div className="bg-gradient-to-r from-pink-500 to-rose-400 rounded-3xl p-8 text-white shadow-lg mb-8 text-center md:text-left flex flex-col md:flex-row items-center justify-between">
          <div>
            <h2 className="text-3xl font-extrabold mb-2">Encuentra el detalle perfecto 🌹</h2>
            <p className="text-pink-100 text-sm max-w-md">
              Explora nuestros ramos, arreglos y accesorios. Haz clic en cualquier producto para ver los detalles y envía tu pedido directo a nuestro WhatsApp.
            </p>
          </div>
        </div>

        {/* Search & Categories Bar */}
        <div className="flex flex-col md:flex-row gap-4 mb-8 justify-between items-stretch md:items-center">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3.5 top-3.5 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Buscar ramo, arreglo o flor..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-11 pr-4 py-3 rounded-2xl border border-pink-200 bg-white shadow-sm focus:outline-none focus:ring-2 focus:ring-pink-500 transition text-sm"
            />
          </div>

          {/* Category Filter Pills */}
          <div className="flex items-center gap-2 overflow-x-auto pb-2 md:pb-0 scrollbar-none">
            <button
              onClick={() => setSelectedCategory('ALL')}
              className={`px-4 py-2.5 rounded-xl font-semibold text-xs whitespace-nowrap transition ${
                selectedCategory === 'ALL'
                  ? 'bg-pink-600 text-white shadow-sm'
                  : 'bg-white text-gray-600 border border-pink-100 hover:bg-pink-50'
              }`}
            >
              Todos
            </button>
            {dynamicCategories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.name)}
                className={`px-4 py-2.5 rounded-xl font-semibold text-xs whitespace-nowrap transition ${
                  selectedCategory === cat.name
                    ? 'bg-pink-600 text-white shadow-sm'
                    : 'bg-white text-gray-600 border border-pink-100 hover:bg-pink-50'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        {/* Grid de Productos */}
        {loading ? (
          <div className="text-center py-20 text-pink-600 font-medium">
            Cargando el catálogo de flores...
          </div>
        ) : filteredProducts.length === 0 ? (
          <div className="text-center py-20 text-gray-400">
            No se encontraron productos coincidentes.
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredProducts.map((product) => (
              <ProductCard
                key={product.id}
                product={product}
                onSelect={(p) => setSelectedProduct(p)}
              />
            ))}
          </div>
        )}
      </main>

      {/* Product Detail Modal */}
      <ProductDetailModal
        product={selectedProduct}
        isOpen={Boolean(selectedProduct)}
        onClose={() => setSelectedProduct(null)}
      />

      {/* Drawer Carrito */}
      <CartDrawer
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        whatsappNumber={WHATSAPP_NUMBER}
      />
    </div>
  );
}
